const { parseFrontmatter } = require("union-receiver-parser");

exports.loadPromptTemplate = function loadPromptTemplate(content) {
  const diagnostics = [];
  const parsed = parseFrontmatter(content);
  if (!parsed.ok) {
    diagnostics.push({
      code: "parse_failed",
      message: parsed.error.message,
    });
  }
  return diagnostics;
};
